cd /tmp/pub/wt26; R=repos/appalex47-lab/Copy-Creative-Intelligence; C=2366ee1f4f57b0389bc7baac55e57d3290c6fe69; B=c3adaf97588ce3b8fef075a44aff6336f4e8c266; P=docs/fase0/expediente_final_v26; BR=audit/fase0-v26-review
echo "# Verificación remota posterior al push del commit del expediente V26 ($(date -u +%FT%TZ)); repositorio appalex47-lab/Copy-Creative-Intelligence; rama $BR"
echo "PV01 rama V26: ls-remote=$(git ls-remote origin refs/heads/$BR | cut -f1) REST=$(gh api $R/git/ref/heads/$BR --jq .object.sha) esperado=$C"
echo "PV02 padre del commit del expediente V26: $(gh api $R/commits/$C --jq .parents[0].sha) (esperado $B); nº de padres=$(gh api $R/commits/$C --jq '.parents|length')"
gh api "$R/git/trees/$C?recursive=1" --jq '.tree[]|select(.type=="blob")|"\(.sha) \(.path)"' | sort > /tmp/pub/v26/pv_rtree.txt; git ls-tree -r $C | awk '{print $3" "$4}' | sort > /tmp/pub/v26/pv_ltree.txt
echo "PV03 árbol remoto = árbol local: $(cmp -s /tmp/pub/v26/pv_rtree.txt /tmp/pub/v26/pv_ltree.txt && echo SI || echo NO) ($(wc -l < /tmp/pub/v26/pv_rtree.txt) blobs; truncado=$(gh api "$R/git/trees/$C?recursive=1" --jq .truncated)); archivos bajo $P/ en GitHub=$(grep -c " $P/" /tmp/pub/v26/pv_rtree.txt)"
RAW="Accept: application/vnd.github.raw"; gh api -H "$RAW" "$R/contents/$P/MANIFIESTO_SHA256_V26.txt?ref=$C" > /tmp/pub/v26/pv_man.txt
echo "PV04 manifiesto remoto idéntico al local: $(cmp -s /tmp/pub/v26/pv_man.txt $P/MANIFIESTO_SHA256_V26.txt && echo SI || echo NO); entradas=$(wc -l < /tmp/pub/v26/pv_man.txt); existen en el árbol remoto: $(awk '{print $2}' /tmp/pub/v26/pv_man.txt | while read p; do grep -qF " $P/$p" /tmp/pub/v26/pv_rtree.txt && echo 1; done | wc -l); sha256 del manifiesto remoto=$(sha256sum < /tmp/pub/v26/pv_man.txt | cut -d' ' -f1)"
sed 's/  / /' /tmp/pub/v26/pv_man.txt | xargs -P8 -L1 bash -c 'h=$0; p=$1; r=$(gh api -H "Accept: application/vnd.github.raw" "'$R'/contents/'$P'/$p?ref='$C'" | sha256sum | cut -d" " -f1); [ "$r" = "$h" ] && echo OK || echo "DISCREPA $p"' > /tmp/pub/v26/pv_dl.txt
echo "PV05 archivos descargados de GitHub y comparados con el manifiesto V26: $(grep -c ^OK /tmp/pub/v26/pv_dl.txt) OK, $(grep -c DISCREPA /tmp/pub/v26/pv_dl.txt) discrepancias"
echo "PV06 diferencia de árboles remotos HEAD V25 -> commit V26 (la API de commits de GitHub limita a 300 archivos por commit y este commit tiene $(git show --stat --format= $C | tail -1 | sed 's/^ *//'); por eso se compara por árboles): añadidos=$(comm -13 /tmp/pub/v26/w03_remoto.txt /tmp/pub/v26/pv_rtree.txt | wc -l); eliminados o modificados=$(comm -23 /tmp/pub/v26/w03_remoto.txt /tmp/pub/v26/pv_rtree.txt | wc -l); añadidos fuera de $P/=$(comm -13 /tmp/pub/v26/w03_remoto.txt /tmp/pub/v26/pv_rtree.txt | grep -vc " $P/")"
echo "PV07 SHA remotos: main=$(git ls-remote origin refs/heads/main | cut -f1) V20=$(git ls-remote origin refs/heads/audit/fase0-v19-review | cut -f1) V23=$(git ls-remote origin refs/heads/audit/fase0-v23-review | cut -f1) V24=$(git ls-remote origin refs/heads/audit/fase0-v24-review | cut -f1) V25=$(git ls-remote origin refs/heads/audit/fase0-v25-review | cut -f1)"
echo "PV08 PRs (todos los estados)=$(gh api "$R/pulls?state=all" --jq length); V26 respecto a V25: $(gh api $R/compare/audit%2Ffase0-v25-review...$C --jq '"\(.status) ahead_by=\(.ahead_by) behind_by=\(.behind_by)"'); V26 respecto a main: $(gh api $R/compare/main...$C --jq '"\(.status) ahead_by=\(.ahead_by) behind_by=\(.behind_by)"')"
echo "PV09 funcional/infra: rutas añadidas por V26 en docs/fase0/(herramientas|historico)/ o fuera de docs/fase0/=$(comm -13 /tmp/pub/v26/w03_remoto.txt /tmp/pub/v26/pv_rtree.txt | awk '{print $2}' | grep -cE '^docs/fase0/(herramientas|historico)/') + $(comm -13 /tmp/pub/v26/w03_remoto.txt /tmp/pub/v26/pv_rtree.txt | awk '{print $2}' | grep -vc '^docs/fase0/'); árbol de herramientas V26 vs V25: $(gh api "$R/contents/docs/fase0/herramientas?ref=$C" --jq '[.[].sha]|join(",")' | md5sum | cut -c1-8) vs $(gh api "$R/contents/docs/fase0/herramientas?ref=$B" --jq '[.[].sha]|join(",")' | md5sum | cut -c1-8)"
echo "PV10 archivos clave accesibles (bytes): $(for f in LEEME_V26.md INFORME_AUDITORIA_FINAL_V26.md INFORME_CONCILIACION_CONTROLES_V26.md MATRIZ_CONTROLES_V26.csv MATRIZ_CAMBIOS_V25_V26.md REPORTE_VALIDACION_V26.md REPORTE_VERIFICACION_REMOTA_V26.md MANIFIESTO_SHA256_V26.txt; do echo -n "$f=$(gh api "$R/contents/$P/$f?ref=$C" --jq .size) "; done)"
gh api -H "$RAW" "$R/contents/$P/MATRIZ_CONTROLES_V26.csv?ref=$C" > /tmp/pub/v26/pv_mat.csv; gh api -H "$RAW" "$R/contents/$P/EJECUCIONES_CONTROLES_V26.csv?ref=$C" > /tmp/pub/v26/pv_exe.csv; gh api -H "$RAW" "$R/contents/$P/LEEME_V26.md?ref=$C" > /tmp/pub/v26/pv_leeme.md
python3 -I - <<'P'
import csv,re
m=list(csv.DictReader(open("/tmp/pub/v26/pv_mat.csv",encoding="utf-8",newline=""))); x=list(csv.DictReader(open("/tmp/pub/v26/pv_exe.csv",encoding="utf-8",newline=""))); l=open("/tmp/pub/v26/pv_leeme.md",encoding="utf-8").read()
c=lambda k:sum(r["Estado"]==k for r in m); e=lambda k:sum(r["Resultado"]==k for r in x)
g=dict(re.findall(r"^\| ([^|]+?) \| (\d+) \|$",l,re.M)); ok=g=={"Total de controles únicos":str(len(m)),"Total de ejecuciones":str(len(x)),"Controles PASS":str(c("PASS")),"Controles FAIL":str(c("FAIL")),"Controles BLOCKED":str(c("BLOCKED")),"Controles NOT VERIFIED":str(c("NOT VERIFIED")),"Controles PARTIAL":str(c("PARTIAL")),"Ejecuciones PASS":str(e("PASS")),"Ejecuciones FAIL":str(e("FAIL")),"Ejecuciones BLOCKED":str(e("BLOCKED")),"Ejecuciones NOT VERIFIED":str(e("NOT VERIFIED")),"Ejecuciones PARTIAL":str(e("PARTIAL"))}
print("PV11 matriz y ejecuciones remotas recontadas: controles=%d ejecuciones=%d PASS=%d FAIL=%d BLOCKED=%d NOT VERIFIED=%d PARTIAL=%d; ejecuciones PASS=%d FAIL=%d PARTIAL=%d; tabla del LEEME remoto coincide=%s"%(len(m),len(x),c("PASS"),c("FAIL"),c("BLOCKED"),c("NOT VERIFIED"),c("PARTIAL"),e("PASS"),e("FAIL"),e("PARTIAL"),ok))
P
